-- =============================================
-- Import Missing 563 Products from CSV to Products Table
-- Generated from ITEM_LIST_WITH_CATEGORY_IDS.csv
-- =============================================

-- Check current count before import
SELECT 'Before Import' AS Stage, COUNT(*) AS ProductCount FROM Products;

-- Start transaction
BEGIN TRANSACTION;

-- Biscuit Choc Chip
IF NOT EXISTS (SELECT 1 FROM Products WHERE ProductCode = 'BIS- CHC-EAC')
BEGIN
    INSERT INTO Products (ProductCode, ProductName, CategoryID, SubcategoryID, ItemType, BaseUoM, IsActive, CreatedDate)
    VALUES ('BIS- CHC-EAC', 'Biscuit Choc Chip', 14, NULL, 'internal', 'ea', 1, GETDATE());
    PRINT 'Inserted: BIS- CHC-EAC - Biscuit Choc Chip';
END
ELSE
BEGIN
    -- Update CategoryID if product exists
    UPDATE Products 
    SET CategoryID = 14, 
        ItemType = 'internal',
        BaseUoM = 'ea'
    WHERE ProductCode = 'BIS- CHC-EAC';
    PRINT 'Updated: BIS- CHC-EAC - Biscuit Choc Chip';
END

