-- Check count after import
SELECT 'After Import' AS Stage, COUNT(*) AS ProductCount FROM Products;

-- Verify we have 1,587 products
SELECT 
    COUNT(*) AS TotalProducts,
    1587 AS ExpectedProducts,
    COUNT(*) - 1587 AS Difference,
    CASE 
        WHEN COUNT(*) = 1587 THEN 'âœ“ SUCCESS - Products table now has 1,587 products'
        ELSE 'âš  Still missing ' + CAST(1587 - COUNT(*) AS VARCHAR) + ' products'
    END AS Status
FROM Products;

PRINT 'Import complete! Processed 1586 products from CSV.';
